import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

const Example = () => (
  <Button
    variant="outline"
    onClick={() => {
      const id = toast.add({ title: "Syncing changes…", type: "loading", timeout: 0 });
      window.setTimeout(() => {
        toast.update(id, { title: "Changes synced", type: "success", timeout: 4000 });
      }, 1200);
    }}
  >
    Show progress toast
  </Button>
);

export default Example;
